import json, os, re

d = os.environ.get('RLM_SESSION_DIR', '')
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Keys:", sorted(G.keys()))

# Print demo input 1 and output 1 side by side
demo_in_1 = G['Demo pair 1 input']
demo_out_1 = G['Demo pair 1 output']

print("\n=== DEMO INPUT 1 ===")
for r, row in enumerate(demo_in_1):
    print(f"R{r}: {' '.join(map(str,row))}")

print("\n=== DEMO OUTPUT 1 ===")
for r, row in enumerate(demo_out_1):
    print(f"R{r}: {' '.join(map(str,row))}")

# Find 3x3 blocks in demo input 1
def find_3x3_blocks(grid):
    blocks = []
    h, w = len(grid), len(grid[0])
    for r in range(h - 2):
        for c in range(w - 2):
            val = grid[r][c]
            # Check if this starts a 3x3 block of the same value
            is_block = True
            for dr in range(3):
                for dc in range(3):
                    if grid[r+dr][c+dc] != val:
                        is_block = False
                        break
                if not is_block:
                    break
            if is_block:
                center_r, center_c = r + 1, c + 1
                blocks.append((val, center_r, center_c))
    return blocks

blocks = find_3x3_blocks(demo_in_1)
print("\n\n3x3 blocks found in Demo Input 1:")
for val, cr, cc in blocks:
    print(f"Value {val} at center ({cr}, {cc})")

# Proposed transformation: fill center row and center column with the block's color
def transform_by_3x3_blocks(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # copy

    blocks = find_3x3_blocks(grid)
    # Apply transformations (order might matter - use later ones on top?)
    for val, cr, cc in blocks:
        # Fill entire row cr with val
        for c in range(w):
            if result[cr][c] != val:
                result[cr][c] = val
        # Fill entire column cc with val  
        for r in range(h):
            if result[r][cc] != val:
                result[r][cc] = val

    return result

