                        left_ok = False
                        break
                for dc in range(1, w-c):
                    if result[r][c+dc] == 0:
                        right_ok = False
                        break
                if left_ok and right_ok and c > 0 and c < w-1:
                    can_cast_horizontally = True

                # Vertical cast check
                up_ok = True
                down_ok = True
                for dr in range(1, r+1):
                    if result[r-dr][c] == 0:
                        up_ok = False
                        break
                for dr in range(1, h-r):
                    if result[r+dr][c] == 0:
                        down_ok = False
                        break
                if up_ok and down_ok and r > 0 and r < h-1:
                    can_cast_vertically = True

                if can_cast_horizontally or can_cast_vertically:
                    casters.append((r, c))

    # Apply casting
    for src_r, src_c in casters:
        color = grid_in[src_r][src_c]

        # Cast horizontally left
        for c in range(src_c - 1, -1, -1):
            if result[src_r][c] != 0:
                break
