def block_raycast_transform(grid_in):
    h, w = len(grid_in), len(grid_in[0])

    # Find all 3x3 blocks
    blocks = {}
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid_in[r][c]
            if color != 0:
                is_block = True
                for dr in range(3):
                    for dc in range(3):
                        if grid_in[r + dr][c + dc] != color:
                            is_block = False
                            break
                    if not is_block:
                        break
                if is_block:
                    blocks[(r, c)] = color

    # Make a working copy of ORIGINAL grid (don't modify during casting)
    result = [row[:] for row in grid_in]

    for (top, left), color in blocks.items():
        cr, cc = top + 1, left + 1

        # Cast center row horizontally
        # Left direction
        for c in range(cc - 1, -1, -1):
            if grid_in[cr][c] != 0:  # Stop at pre-existing non-zero
                break
            result[cr][c] = color

        # Right direction
        for c in range(cc + 1, w):
            if grid_in[cr][c] != 0:
                break
            result[cr][c] = color

        # Cast center column vertically
        # Up direction
        for r in range(cr - 1, -1, -1):
            if grid_in[r][cc] != 0:
                break
            result[r][cc] = color

        # Down direction
        for r in range(cr + 1, h):
            if grid_in[r][cc] != 0:
                break
            result[r][cc] = color

    return result

